"""Integrity-checked registry for retained V106-V304 report contracts.

The milestone implementations are compatibility evidence contracts, not live
execution code.  Their exact source is stored as one compressed, immutable
payload so active code never imports a version-numbered package.  Five current
operator-proof stages have maintained stable modules and are registered
directly.

Only bundled source with the pinned digest is executed.  No filesystem,
network, package discovery, or authority write is involved in contract
loading.
"""

from __future__ import annotations

import base64
import hashlib
import json
import zlib
from functools import lru_cache
from types import ModuleType
from typing import Any, Callable

from predator_mesh.operator_proof_stages import command_seal
from predator_mesh.operator_proof_stages import execute_once
from predator_mesh.operator_proof_stages import post_proof
from predator_mesh.operator_proof_stages import reconcile
from predator_mesh.operator_proof_stages import starvation

