MIN_VERSION = 106
MAX_VERSION = 304

_STABLE_CONTRACTS: dict[int, tuple[ModuleType, Callable[..., Any]]] = {
    297: (command_seal, command_seal.CommandSealReportFactory),
    298: (execute_once, execute_once.ExecuteOnceProofReportFactory),
    300: (reconcile, reconcile.ReconcileForensicReportFactory),
    301: (post_proof, post_proof.PostProofRouteReportFactory),
    303: (starvation, starvation.ProofStarvationReportFactory),
}
_EMBEDDED_VERSIONS = frozenset(range(MIN_VERSION, MAX_VERSION + 1)) - frozenset(
    _STABLE_CONTRACTS
)

