@lru_cache(maxsize=1)
def _contract_sources() -> dict[int, str]:
    raw = zlib.decompress(base64.b85decode(_PAYLOAD_B85))
    actual_hash = hashlib.sha256(raw).hexdigest()
    if actual_hash != PAYLOAD_SHA256:
        raise RuntimeError(
            "retained report-contract registry failed integrity validation"
        )
    decoded = json.loads(raw)
    sources = {int(version): source for version, source in decoded.items()}
    if frozenset(sources) != _EMBEDDED_VERSIONS:
        raise RuntimeError(
            "retained report-contract registry has incomplete version coverage"
        )
    return sources


@lru_cache(maxsize=None)
def load_contract(version: int) -> ModuleType:
    """Return one retained report contract without package discovery."""

    stable = _STABLE_CONTRACTS.get(version)
    if stable is not None:
        return stable[0]
    try:
        source = _contract_sources()[version]
    except KeyError as exc:
        raise LookupError(f"unsupported report contract V{version}") from exc

    module = ModuleType(f"predator_mesh.report_contract_v{version}")
    module.__package__ = "predator_mesh"
    code = compile(
        source,
        f"<dummy-retained-report-contract-v{version}>",
        "exec",
    )
    exec(code, module.__dict__)
    return module


def factory_type(version: int) -> Callable[..., Any]:
    """Return the exact factory class for a retained contract."""

    stable = _STABLE_CONTRACTS.get(version)
    if stable is not None:
        return stable[1]
    stage = load_contract(version)
    return getattr(stage, f"V{version}ReportFactory")


def source_sha256(version: int) -> str:
    """Return a stable digest for one embedded compatibility contract."""

    try:
        source = _contract_sources()[version]
    except KeyError as exc:
        raise LookupError(f"V{version} is a maintained stable stage") from exc
    return hashlib.sha256(source.encode("utf-8")).hexdigest()


__all__ = [
    "MAX_VERSION",
    "MIN_VERSION",
    "PAYLOAD_SHA256",
    "factory_type",
    "load_contract",
    "source_sha256",
]
